declare(strict_types=1);if(!defined('REDFOX_SKIP_BOTAPI_ROUTER'))define('REDFOX_SKIP_BOTAPI_ROUTER',true);require_once __DIR__.'/../lib/Security.php';redfox_secure_session_start();require_once __DIR__.'/../config.php';require_once __DIR__.'/../botapi.php';require_once __DIR__.'/lib/icons.php';$q=$pdo->prepare('SELECT * FROM admin WHERE username=? LIMIT 1');$q->execute([$_SESSION['user']??'']);$admin=$q->fetch(PDO::FETCH_ASSOC);if(!$admin){header('Location:login.php');exit;}$main=($admin['rule']??'')==='administrator';try{rx_require_schema($pdo,['help','content_categories']);}catch(Throwable$e){header('Location:migrations.php?required=help_categories');exit;}$flash='';$ft='success';$slug=fn($s)=>trim(strtolower(preg_replace('/[^A-Za-z0-9]+/','-',trim((string)$s))),'-')?:'cat-'.bin2hex(random_bytes(3));
$uploadTelegram=function(array$f,string$type)use($admin){$err=(int)($f['error']??UPLOAD_ERR_NO_FILE);if($err===UPLOAD_ERR_NO_FILE)return'';if($err!==UPLOAD_ERR_OK||!is_uploaded_file((string)$f['tmp_name']))throw new RuntimeException('آپلود رسانه ناموفق بود.');if((int)$f['size']>25*1024*1024)throw new RuntimeException('رسانه حداکثر ۲۵ مگابایت باشد.');$mime=(new finfo(FILEINFO_MIME_TYPE))->file($f['tmp_name']);if($type==='photo'&&!str_starts_with($mime,'image/'))throw new RuntimeException('فایل انتخابی تصویر نیست.');if($type==='video'&&!str_starts_with($mime,'video/'))throw new RuntimeException('فایل انتخابی ویدیو نیست.');$method=$type==='photo'?'sendPhoto':'sendVideo';$field=$type==='photo'?'photo':'video';$r=telegram($method,['chat_id'=>(string)$admin['id_admin'],$field=>new CURLFile($f['tmp_name'],$mime,basename($f['name'])),'caption'=>'رسانه آموزش در پنل Red Fox']);if(empty($r['ok']))throw new RuntimeException('ارسال رسانه به Telegram ناموفق بود: '.($r['description']??''));if($type==='photo'){$arr=$r['result']['photo']??[];$last=end($arr);return(string)($last['file_id']??'');}return(string)($r['result']['video']['file_id']??'');};
if(($_SERVER['REQUEST_METHOD']??'')==='POST'&&$main){try{$a=(string)($_POST['action']??'');if($a==='cat_add'){$name=mb_substr(trim((string)$_POST['name']),0,191);$pdo->prepare("INSERT INTO content_categories(section,name,slug,enabled,sort_order,created_at) VALUES('help',?,?,1,?,?)")->execute([$name,$slug($_POST['slug']??$name),(int)($_POST['sort_order']??0),time()]);$flash='دسته آموزش ساخته شد.';}elseif($a==='cat_edit'){$id=(int)$_POST['id'];$name=mb_substr(trim((string)$_POST['name']),0,191);$pdo->beginTransaction();$q=$pdo->prepare("SELECT name FROM content_categories WHERE id=? AND section='help' FOR UPDATE");$q->execute([$id]);$old=(string)$q->fetchColumn();if($old==='')throw new RuntimeException('دسته پیدا نشد.');$pdo->prepare("UPDATE content_categories SET name=?,enabled=?,sort_order=? WHERE id=? AND section='help'")->execute([$name,isset($_POST['enabled'])?1:0,(int)$_POST['sort_order'],$id]);$pdo->prepare('UPDATE help SET category=? WHERE category=?')->execute([$name,$old]);$pdo->commit();$flash='دسته و آموزش‌های آن بروزرسانی شد.';}elseif($a==='cat_delete'){$id=(int)$_POST['id'];$q=$pdo->prepare("SELECT name FROM content_categories WHERE id=? AND section='help'");$q->execute([$id]);$name=(string)$q->fetchColumn();$c=$pdo->prepare('SELECT COUNT(*) FROM help WHERE category=?');$c->execute([$name]);if((int)$c->fetchColumn()>0)throw new RuntimeException('ابتدا آموزش‌های این دسته را منتقل یا حذف کنید.');$pdo->prepare("DELETE FROM content_categories WHERE id=? AND section='help'")->execute([$id]);$flash='دسته حذف شد.';}elseif($a==='add'||$a==='edit'){$id=(int)($_POST['id']??0);$name=mb_substr(trim((string)$_POST['name_os']),0,480);$cat=trim((string)$_POST['category']);$desc=mb_substr(trim((string)$_POST['Description_os']),0,10000);$type=(string)($_POST['media_type']??'text');if(!in_array($type,['text','photo','video'],true))$type='text';$v=$pdo->prepare("SELECT COUNT(*) FROM content_categories WHERE section='help' AND name=?");$v->execute([$cat]);if((int)$v->fetchColumn()!==1)throw new RuntimeException('دسته آموزش نامعتبر است.');$media=$uploadTelegram($_FILES['media']??[],$type);if($a==='add')$pdo->prepare('INSERT INTO help(name_os,Media_os,type_Media_os,category,Description_os) VALUES(?,?,?,?,?)')->execute([$name,$media,$media!==''?$type:'text',$cat,$desc]);else{if($media!=='')$pdo->prepare('UPDATE help SET name_os=?,Media_os=?,type_Media_os=?,category=?,Description_os=? WHERE id=?')->execute([$name,$media,$type,$cat,$desc,$id]);else$pdo->prepare('UPDATE help SET name_os=?,category=?,Description_os=? WHERE id=?')->execute([$name,$cat,$desc,$id]);}$flash='آموزش ذخیره شد.';}elseif($a==='delete'){$pdo->prepare('DELETE FROM help WHERE id=?')->execute([(int)$_POST['id']]);$flash='آموزش حذف شد.';}}catch(Throwable$e){if($pdo->inTransaction())$pdo->rollBack();$flash=redfox_public_exception($e, 'panel/help.php');$ft='error';}}
$cats=$pdo->query("SELECT * FROM content_categories WHERE section='help' AND id IN(SELECT MIN(id) FROM content_categories WHERE section='help' GROUP BY LOWER(TRIM(name))) ORDER BY sort_order,id")->fetchAll(PDO::FETCH_ASSOC);$helps=$pdo->query('SELECT * FROM help ORDER BY category,id')->fetchAll(PDO::FETCH_ASSOC);
?><!doctype html><html lang="fa" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>آموزش‌ها</title><link rel="stylesheet" href="css/theme.css"><style>.rx-content-manager .card{background:linear-gradient(145deg,var(--surface-1),var(--surface-2));border:1px solid var(--border-soft);box-shadow:0 8px 22px rgba(0,0,0,.12);padding:14px!important}.rx-content-manager form{display:flex;gap:6px;flex-wrap:wrap;align-items:center}.rx-content-manager input,.rx-content-manager select,.rx-content-manager textarea{border:1px solid var(--border-mid);border-radius:9px;background:var(--surface-1);color:var(--text-main);padding:6px 8px;font-size:12px;font-family:inherit}.rx-content-manager textarea{min-width:210px;min-height:58px}.rx-content-manager .app-table tr:hover{background:var(--accent-soft)}.rx-content-manager .btn{border-radius:8px;padding:6px 10px!important;font-size:11px!important;min-height:30px!important}.rx-content-manager code{font-size:11px}@media(max-width:700px){.rx-content-manager form>*{width:100%!important}.rx-content-manager .table-wrap{overflow:auto}}</style></head><body class="rx-content-manager"><section id="container"><?php include'header.php';?><section id="main-content"><div class="wrapper"><div class="page-head"><h1 class="page-head__title">مدیریت آموزش‌ها</h1><div class="page-head__sub">دسته‌بندی مستقل، متن، عکس و ویدیو؛ فقط دسته‌های فعال در ربات دیده می‌شوند.</div></div><?php if($flash):?><div class="card <?=$ft?>"><?=htmlspecialchars($flash)?></div><?php endif;?>
<div class="card"><h2>دسته‌بندی آموزش</h2><form method="post"><input type="hidden" name="action" value="cat_add"><input name="name" placeholder="مثلاً ویندوز" required><input name="slug" placeholder="windows"><input type="number" name="sort_order" value="0"><button class="btn btn-success">ایجاد دسته</button></form><table class="app-table"><tr><th>نام</th><th>شناسه</th><th>ترتیب</th><th>مدیریت</th></tr><?php foreach($cats as$c):$fid='help-cat-'.$c['id'];?><tr><td><input form="<?=$fid?>" name="name" value="<?=htmlspecialchars($c['name'])?>"></td><td><code><?=htmlspecialchars($c['slug'])?></code></td><td><input form="<?=$fid?>" type="number" name="sort_order" value="<?=$c['sort_order']?>" style="width:70px"></td><td><form id="<?=$fid?>" method="post"><input type="hidden" name="action" value="cat_edit"><input type="hidden" name="id" value="<?=$c['id']?>"><label><input type="checkbox" name="enabled" <?=$c['enabled']?'checked':''?>> فعال</label><button class="btn btn-primary">ذخیره تغییرات</button></form><form method="post" onsubmit="return confirm('حذف دسته؟')"><input type="hidden" name="action" value="cat_delete"><input type="hidden" name="id" value="<?=$c['id']?>"><button class="btn btn-danger">حذف</button></form></td></tr><?php endforeach;?></table></div>
<div class="card"><h2>افزودن آموزش</h2><form method="post" enctype="multipart/form-data"><input type="hidden" name="action" value="add"><input name="name_os" placeholder="عنوان" required><select name="category" required><option value="">انتخاب دسته</option><?php foreach($cats as$c):?><option <?=!$c['enabled']?'disabled':''?>><?=htmlspecialchars($c['name'])?></option><?php endforeach;?></select><select name="media_type"><option value="text">متنی</option><option value="photo">عکس</option><option value="video">ویدیو</option></select><input type="file" name="media" accept="image/*,video/*"><textarea name="Description_os" placeholder="متن آموزش"></textarea><button class="btn btn-success">ذخیره آموزش</button></form><p class="page-guide">برای عکس یا ویدیو، فایل از طریق ربات اصلی به Telegram ارسال و file_id معتبر ذخیره می‌شود.</p></div>
<div class="card"><h2>فهرست آموزش‌ها</h2><div class="table-wrap"><table class="app-table"><tr><th>عنوان</th><th>دسته</th><th>نوع</th><th>ویرایش</th></tr><?php foreach($helps as$h):?><tr><td><?=htmlspecialchars($h['name_os'])?></td><td><?=htmlspecialchars($h['category'])?></td><td><?=htmlspecialchars(['text'=>'متن','photo'=>'عکس','video'=>'ویدیو'][$h['type_Media_os']]??$h['type_Media_os'])?></td><td><form method="post" enctype="multipart/form-data"><input type="hidden" name="action" value="edit"><input type="hidden" name="id" value="<?=$h['id']?>"><input name="name_os" value="<?=htmlspecialchars($h['name_os'])?>"><select name="category"><?php foreach($cats as$c):?><option <?=$h['category']===$c['name']?'selected':''?>><?=htmlspecialchars($c['name'])?></option><?php endforeach;?></select><select name="media_type"><option value="text" <?=$h['type_Media_os']==='text'?'selected':''?>>متن</option><option value="photo" <?=$h['type_Media_os']==='photo'?'selected':''?>>عکس</option><option value="video" <?=$h['type_Media_os']==='video'?'selected':''?>>ویدیو</option></select><input type="file" name="media" accept="image/*,video/*"><textarea name="Description_os"><?=htmlspecialchars($h['Description_os'])?></textarea><button class="btn btn-primary">ذخیره</button></form><form method="post" onsubmit="return confirm('حذف آموزش؟')"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$h['id']?>"><button class="btn btn-danger">حذف</button></form></td></tr><?php endforeach;?></table></div></div></div></section></section></body></html>
